// TooltipContent.jsx
import React, { useState, useEffect } from 'react';
import { useTooltip } from './TooltipContext';

const TooltipContent = ({ children, tooltipId }) => {
  const { openTooltipId, closeTooltip } = useTooltip();
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    if (openTooltipId === tooltipId) {
      setIsVisible(true);
    } else {
      setIsVisible(false);
    }
  }, [openTooltipId, tooltipId]);

  const handleOutsideClick = (event) => {
    if (!event.target.closest('.tooltip-content')) {
      closeTooltip();
    }
  };

  useEffect(() => {
    if (isVisible) {
      document.addEventListener('click', handleOutsideClick);
      return () => {
        document.removeEventListener('click', handleOutsideClick);
      };
    }
  }, [isVisible, closeTooltip]);

  if (!isVisible) {
    return null;
  }

  return (
    <div className="tooltip-content" onClick={(e) => e.stopPropagation()}>
      {children}
    </div>
  );
};

export default TooltipContent;
