        {
            // Construct the URL to query the Steam VAC status
            string url = $"https://partner.steamstats.com/api/VAC?key=YOUR_API_KEY&steamid={steam64Id}";

            // Make the HTTP request
            using (WebClient client = new WebClient())
            {
                // Download the XML data
                string xmlData = client.DownloadString(url);

                // Parse the XML data
                XmlDocument doc = new XmlDocument();
                doc.LoadXml(xmlData);

                // Extract the VAC ban information
                int vacBans = 0;
                string lastBanDate = "Never";

                XmlNodeList banNodes = doc.GetElementsByTagName("VACBanned");
                foreach (XmlNode banNode in banNodes)
                {
                    vacBans++;
                    XmlNode dateNode = banNode.SelectSingleNode("Date");
                    if (dateNode != null)
                    {
                        lastBanDate = dateNode.InnerText;
                    }
                }

                // Print the results
                Console.WriteLine($"Steam64ID: {steam64Id}");
                Console.WriteLine($"VAC Bans: {vacBans}");
                Console.WriteLine($"Last VAC Ban Date: {lastBanDate}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
